def hub_label(identifier,full=False):
    identifier=str(identifier)
    return identifier+' — '+(HUB_DESCRIPTIONS if full else HUB_CITIES)[identifier]

def customer_label(customer):
    return customer.customer_id+' — '+customer.name.replace('ОЭЗ','особая экономическая зона')

def route_label(identifier): return ROUTE_NAMES.get(identifier,identifier)
def status_label(identifier): return STATUS_NAMES.get(identifier,identifier)

